#!/usr/bin/env python3
"""Render the browser catalogue from the unchanged seed and explicit annotations."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "docs/corpus.html"


def esc(value):
    return html.escape(str(value), quote=True)


def render():
    seed = json.loads((ROOT / "data/corpus/attested-forms.v1.json").read_text())
    catalog = json.loads((ROOT / "data/corpus/academic-catalog.v1.json").read_text())
    annotations = {item["form_id"]: item for item in catalog["entries"]}
    semantic_labels = {
        "identified_referent": "Referente identificado",
        "identified_name": "Nombre identificado",
        "supported_hypothesis": "Hipótesis interpretativa",
        "contextually_supported": "Interpretación contextual",
        "disputed": "Interpretación discutida",
        "uninterpreted": "Sin interpretación",
    }
    confidence_labels = {"low": "Baja", "medium": "Media", "high": "Alta", "very_high": "Muy alta"}
    cards, links = [], []
    for form in seed["forms"]:
        entry = annotations[form["id"]]
        if entry["linguistic_segmentation"]["status"] != "not_catalogued":
            raise ValueError("New linguistic segmentation needs a reviewed renderer and validation policy")
        fid = esc(form["id"])
        sources = "".join(f'<li><a href="{esc(s["url"])}">{esc(s["citation"])}</a></li>' for s in form["sources"])
        links.append(f'<a href="#{fid}">{esc(form["form"])}</a>')
        cards.append(f'''<article class="catalogue-card" id="{fid}" data-semantic="{esc(form['semantic_status'])}">
  <header><p class="catalogue-kind">Forma aislada documentada · no edición de una inscripción completa</p>
  <h2>{esc(form['form'])}</h2><p class="catalogue-id">Identificador interno: <code>{fid}</code></p></header>
  <dl>
    <dt>Forma de referencia adoptada</dt><dd class="catalogue-reading">{esc(form['form'])}</dd>
    <dt>Descomposición técnica en signos</dt><dd><code class="grapheme-sequence">{esc(' · '.join(form['grapheme_sequence']))}</code><small>Convención grafemática del visor; no separa palabras ni morfemas.</small></dd>
    <dt>Segmentación lingüística</dt><dd class="linguistic-status" data-status="not_catalogued">No incorporada al catálogo. No se ofrece una división léxica o morfológica revisada de esta forma.</dd>
    <dt>Contexto y procedencia de la referencia</dt><dd>{esc(entry['provenance']['context'])}. Soporte o ámbito: {esc(entry['provenance']['support'])}.<small>{esc(entry['provenance']['note'])}</small></dd>
    <dt>Certeza de lectura</dt><dd class="reading-confidence">{esc(confidence_labels[form['reading_confidence']])} · valoración heredada del corpus de IberoLab, sin escala calibrada ni validación externa integral.</dd>
    <dt>Estado de la interpretación</dt><dd><strong class="semantic-label">{esc(semantic_labels[form['semantic_status']])}</strong>. {esc(entry['interpretation'])}</dd>
  </dl>
  <details><summary>Notas de contexto y transcripción</summary><p>{esc(entry['context'])}</p><p>{esc(entry['transcription_note'])}</p></details>
  <h3>Referencias bibliográficas</h3><ul class="catalogue-sources">{sources}</ul>
  <p class="catalogue-actions"><a href="./#{fid}">Ver signos normalizados de esta forma</a> · <a href="#{fid}" aria-label="Enlace directo a {esc(form['form'])}">Enlace a la ficha</a></p>
</article>''')
    return '''<!doctype html>
<!-- Generated by scripts/render_academic_catalog.py; edit data, not this snapshot. -->
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="dark"><meta name="description" content="Consulta once formas ibéricas documentadas, sus transcripciones, fuentes e incertidumbres directamente en el navegador. Alcance y segmentaciones disponibles explícitos.">
<link rel="canonical" href="https://iberolab-es.github.io/IberoLab/corpus.html"><link rel="icon" href="assets/brand/iberolab-mark.svg" type="image/svg+xml"><title>IberoLab — Corpus documentado en el navegador</title>
<link rel="stylesheet" href="public-site.css"><link rel="stylesheet" href="corpus.css"></head>
<body><a class="skip-link" href="#contenido">Saltar al contenido</a>
<nav class="public-nav" aria-label="Navegación principal"><div class="public-nav-inner"><a class="public-brand" href="./"><img src="assets/brand/iberolab-mark.svg" alt=""><span class="public-brand-name">Ibero<span>Lab</span></span></a><div class="public-links"><a href="corpus.html" aria-current="page">Corpus documentado</a><a href="academia.html">Documentación académica</a><a href="historia.html">Historia</a><a href="convertir.html">Conversor experimental</a></div></div></nav>
<main class="page-shell" id="contenido" tabindex="-1">
<header class="page-hero"><div class="section-kicker">Consulta académica · sin instalaciones</div><h1>Corpus documentado en el navegador.</h1>
<p>Consulta las transcripciones, la procedencia de las referencias y las incertidumbres del material disponible. Las fichas y la bibliografía se leen aquí; no necesitas GitHub ni instalar software.</p></header>
<section class="catalogue-scope" aria-labelledby="alcance"><h2 id="alcance">Qué contiene y qué falta</h2>
<p><strong>11 formas aisladas documentadas · 0 ediciones de inscripciones completas · 0 segmentaciones lingüísticas incorporadas.</strong></p>
<p>Este conjunto inicial no satisface todavía una consulta extensa de textos ibéricos segmentados. Las divisiones con puntos separan signos para el renderizador: no son segmentaciones léxicas ni morfológicas. La ausencia de una segmentación en estas fichas no significa que la publicación no discuta análisis.</p>
<p>Los identificadores son internos de IberoLab; no se presentan como números de Hesperia o de inventario arqueológico. Las lecturas publicadas y sus convenciones se mantienen separadas de las interpretaciones. <a href="#criterios">Criterios y ampliación gradual</a>.</p></section>
<nav class="catalogue-index" aria-label="Índice de las once formas">''' + "\n".join(links) + '''</nav>
<form id="catalogueTools" class="catalogue-tools" hidden aria-label="Buscar en las fichas"><div><label for="catalogueSearch">Buscar forma, lugar o referencia</label><input id="catalogueSearch" type="search" autocomplete="off" placeholder="Ej.: seltar, Caminreal, Ferrer"></div>
<div><label for="interpretationFilter">Estado de interpretación</label><select id="interpretationFilter"><option value="all">Todos</option><option value="disputed">Interpretación discutida</option><option value="supported_hypothesis">Hipótesis interpretativa</option><option value="contextually_supported">Interpretación contextual</option><option value="identified">Nombre o referente identificado</option></select></div><button id="clearCatalogueFilters" type="button">Restablecer</button></form>
<noscript><p>JavaScript está desactivado: las once fichas y sus referencias siguen disponibles. Puedes usar el índice o la búsqueda de tu navegador.</p></noscript>
<p id="catalogueStatus" role="status" aria-live="polite">11 de 11 fichas disponibles.</p><p id="catalogueEmpty" hidden>No hay coincidencias. Cambia la búsqueda o restablece los filtros.</p>
<section class="catalogue-grid" aria-label="Fichas de formas documentadas">''' + "\n".join(cards) + '''</section>
<section class="section-block" id="criterios"><div class="section-kicker">Evidencia, análisis y límites</div><h2 class="section-title">No confundir los niveles de segmentación.</h2>
<dl class="segmentation-legend"><dt>Descomposición grafemática</dt><dd>Tokens del proyecto usados para seleccionar signos. Disponibles en las once fichas; no acreditan una división lingüística.</dd><dt>Segmentación lingüística documentada</dt><dd>Debe proceder de una publicación identificada, con localizador y revisión especializada registrada. No hay ninguna incorporada todavía.</dd><dt>Hipótesis o análisis discutido</dt><dd>Se atribuirá a sus autores y se conservarán las alternativas. Las hipótesis interpretativas ya presentes no se convierten aquí en segmentaciones.</dd><dt>Texto sin segmentar</dt><dd>Exigirá igualmente una edición documentada del texto y su procedencia. Las formas aisladas actuales no se presentan como textos completos sin segmentar.</dd></dl>
<h3>Ampliación gradual</h3><ol><li>Elegir una inscripción con edición científica y procedencia verificable.</li><li>Registrar por separado identificadores de objeto, transcripción, divisiones originales, restauraciones e hipótesis analíticas.</li><li>Añadir localizadores y atribución para cada división; comprobar derechos y licencias de recursos.</li><li>Obtener revisión especializada de la ficha y sus análisis antes de incorporarla. No se generarán segmentaciones lingüísticas por IA.</li></ol>
<p>La auditoría de fuentes previa comprueba presencia de formas en las publicaciones citadas. No constituye revisión externa integral del catálogo ni validación de todas sus interpretaciones. <a href="academia.html">Alcance de la documentación académica</a> · <a href="metodologia.html#procedimiento">Metodología</a>.</p></section>
<footer class="public-footer"><span>IberoLab · Formas documentadas, no traducciones.</span><a href="./">Volver al inicio</a></footer></main><script src="corpus-catalog.js" defer></script></body></html>
'''


if __name__ == "__main__":
    OUTPUT.write_text(render(), encoding="utf-8")
    print("Generated docs/corpus.html from the documented seed and catalogue annotations.")
